const decoder=new TextDecoder(),encoder=new TextEncoder();let activeGrant=null,publicDocument=null;
const base64=bytes=>{let result='';for(let i=0;i<bytes.length;i+=32768)result+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(result)};
const unbase64=text=>{if(typeof text!=='string'||text.length>7500000)throw Error('授權格式不正確');try{return Uint8Array.from(atob(text),c=>c.charCodeAt(0))}catch{throw Error('授權格式不正確')}};
export const currentAuthorization=()=>activeGrant;
export function validateGrant(payload,keyId,now=Date.now()){if(payload?.version!==1||payload.keyId!==keyId||typeof payload.licenseId!=='string'||typeof payload.subject!=='string')throw Error('授權簽章資料不符合此 MPS');if(payload.notBefore&&(!Number.isFinite(Date.parse(payload.notBefore))||now<Date.parse(payload.notBefore)))throw Error('授權尚未生效');if(payload.expiresAt&&(!Number.isFinite(Date.parse(payload.expiresAt))||now>=Date.parse(payload.expiresAt)))throw Error('授權已到期');if(!Array.isArray(payload.tools)||payload.tools.length>20)throw Error('擴充工具格式不正確');const ids=new Set();for(const tool of payload.tools){if(!/^[a-zA-Z0-9._-]{1,64}$/.test(tool.id)||ids.has(tool.id)||typeof tool.name!=='string'||tool.name.length>80||typeof tool.code!=='string'||tool.code.length>200000||tool.iconSvg&&String(tool.iconSvg).length>5000)throw Error('擴充工具資料不正確');ids.add(tool.id)}return payload}
async function authDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('mps-authorization',1);r.onupgradeneeded=()=>r.result.createObjectStore('grants',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function savedGrant(action,record){const db=await authDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('grants',action==='get'?'readonly':'readwrite'),store=tx.objectStore('grants'),request=action==='get'?store.get('active'):action==='put'?store.put(record):store.delete('active');tx.oncomplete=()=>resolve(request.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('授權儲存失敗'))})}finally{db.close()}}
async function publicKey(){if(!publicDocument){const response=await fetch('license-public-key.json?v=108');if(!response.ok)throw Error('無法讀取授權驗證公鑰');publicDocument=await response.json()}return publicDocument}
async function checkEnvelope(envelope,key){const doc=await publicKey();let decoded;try{decoded=await crypto.subtle.decrypt({name:'AES-GCM',iv:unbase64(envelope.iv)},key,unbase64(envelope.ciphertext))}catch{throw Error('密碼不正確，或授權檔已損壞')}let signed;try{signed=JSON.parse(decoder.decode(decoded))}catch{throw Error('授權內容無效')}const verifyKey=await crypto.subtle.importKey('jwk',doc.publicKey,{name:'ECDSA',namedCurve:'P-256'},false,['verify']);const bytes=unbase64(signed.payload);if(!await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},verifyKey,unbase64(signed.signature),bytes))throw Error('授權簽章無效');return validateGrant(JSON.parse(decoder.decode(bytes)),doc.keyId)}
export async function decryptAuthorization(envelope,password){if(envelope?.format!=='MPS-LICENSE-1'||envelope.kdf?.name!=='PBKDF2'||envelope.kdf.hash!=='SHA-256'||!Number.isInteger(envelope.kdf.iterations)||envelope.kdf.iterations<210000||envelope.kdf.iterations>2000000)throw Error('不是支援的 MPS 授權檔');if(unbase64(envelope.iv).length!==12||unbase64(envelope.kdf.salt).length!==16)throw Error('授權格式不正確');if(!password)throw Error('請輸入授權密碼');const material=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-256',salt:unbase64(envelope.kdf.salt),iterations:envelope.kdf.iterations},material,{name:'AES-GCM',length:256},false,['decrypt']);return{payload:await checkEnvelope(envelope,key),key}}
export async function deleteAuthorization(){await savedGrant('delete');activeGrant=null;window.dispatchEvent(new Event('mps-authorization-removed'));document.body.classList.add('mps-locked');location.reload()}
function unlock(payload){activeGrant=payload;document.body.classList.remove('mps-locked');document.getElementById('mps-license-gate')?.remove();return payload}
export async function requireAuthorization(){if(!crypto?.subtle)throw Error('授權解鎖需要 HTTPS 或 localhost 本機啟動程式');let warning='';try{const stored=await savedGrant('get');if(stored?.envelope&&stored.key)return unlock(await checkEnvelope(stored.envelope,stored.key))}catch(e){warning=e.message}let gate=document.getElementById('mps-license-gate');if(!gate){gate=document.createElement('section');gate.id='mps-license-gate';document.body.append(gate)}gate.innerHTML='<form id="mps-license-form"><h1>MPS 授權解鎖</h1><p>首次使用請載入加密授權檔並輸入密碼。解鎖保存在此瀏覽器，刪除原始檔案不會取消授權。</p><label>授權檔<input id="mps-license-file" type="file" accept=".mpslic,.json" required></label><label>授權密碼<input id="mps-license-password" type="password" autocomplete="current-password" required></label><button id="mps-license-unlock" type="submit">解鎖 MPS</button><p id="mps-license-status" role="status"></p><small>授權在本機解密及驗證，不會上傳授權檔或密碼。</small></form>';document.getElementById('mps-license-status').textContent=warning;return new Promise(resolve=>{document.getElementById('mps-license-form').onsubmit=async event=>{event.preventDefault();const button=document.getElementById('mps-license-unlock'),status=document.getElementById('mps-license-status');button.disabled=true;try{const file=document.getElementById('mps-license-file').files[0];if(!file)throw Error('請選擇授權檔');if(file.size>5*1024*1024)throw Error('授權檔超過 5 MB');const envelope=JSON.parse(await file.text()),{payload,key}=await decryptAuthorization(envelope,document.getElementById('mps-license-password').value);await savedGrant('put',{id:'active',envelope,key});document.getElementById('mps-license-password').value='';resolve(unlock(payload))}catch(e){status.textContent=e.message||'無法解鎖，請確認授權檔與密碼'}finally{button.disabled=false}}})}
